/** The keys of one screen: `Extract<SettingKey, `${S}.${string}`>`. */
export type SettingKeysOfScreen<S extends SettingScreen> = Extract<SettingKey, `${S}.${string}`>;

/** One settings entry — the doc 07 §5.2 field set. */
export interface SettingEntry {
  /** Canonical dotted kebab-case id. */
  key: SettingKey;
  type: SettingType;
  /** UI control hint (G1 control selection). */
  control: SettingControl;
  /** Numeric domain `[min, max]`; `null` when unconstrained. */
  range: readonly [number, number] | null;
  /** Enum members; `null` for non-enum types. */
  enumeration: readonly string[] | null;
  /** Literal default; `null` when the default is referenced from product.toml. */
  default: boolean | number | string | readonly string[] | null;
  /** product.toml path referenced by `default_ref` (rule D1); `null` for literals. */
  defaultRef: string | null;
  /** Description msgid (localization key — never literal prose). */
  description: string;
  restartRequired: boolean;
  /** UI placement (doc 07 §5.2). */
  screen: SettingScreen;
  section: string;
  order: number;
  /** `false` for engine-internal entries (never rendered; CLI + docs only). */
  ui: boolean;
  /** Long flag — unique and disjoint from reserved CLI names (rule D3). */
  cliFlag: string;
  cliShort: string;
  /** Feature gate id; `null` = ungated (doc 05 §6.4). */
  featureGate: string | null;
  /** First product version shipping this entry. */
  since: string;
  /** `user` (persisted, layer 4) or `session` (layer 6) — doc 07 §4.1. */
  scope: 'user' | 'session';
  /** Array merge policy (doc 07 §4.4 rule 3). */
  arrayPolicy: 'replace' | 'append-unique';
  /** VLC-style "show advanced" folding. */
  advanced: boolean;
  /** Version that deprecated this entry; `null` = active. */
  deprecatedIn: string | null;
}

/** Entries per screen in `(section, order)` order (doc 07 §5.4 navigation). */
